    targetQuery: `SELECT i.invoice_id, a.company_name, a.billing_country, i.amount_usd, i.paid_at\nFROM Invoices i\nINNER JOIN Accounts a\n  ON i.account_id = a.account_id\nWHERE i.status = 'PAID'\nORDER BY i.amount_usd DESC;`,
    eli5Story: "Attaching the company profile to each billing receipt so accounting knows which enterprise paid each invoice.",
