    targetQuery: `SELECT s.vessel_imo, s.hold_section,\n       COUNT(b.booking_id) AS total_containers_stowed,\n       SUM(b.gross_weight_metric_tons) AS total_hold_weight_tons,\n       s.max_tonnage,\n       ROUND((SUM(b.gross_weight_metric_tons) / s.max_tonnage) * 100.0, 2) AS hold_capacity_pct\nFROM ContainerBookings b\nINNER JOIN VesselStowageCells s\n  ON b.cell_id = s.cell_id\nGROUP BY s.vessel_imo, s.hold_section, s.max_tonnage\nHAVING SUM(b.gross_weight_metric_tons) > s.max_tonnage * 0.90\nORDER BY hold_capacity_pct DESC;`,
