    schemaSnippet: "`RoleAssumes (event_id VARCHAR(32) PRIMARY KEY, role_arn VARCHAR(128), session_token VARCHAR(64), assumed_at TIMESTAMP)` & `MfaSessions (session_token VARCHAR(64) PRIMARY KEY, user_arn VARCHAR(128), mfa_auth_type VARCHAR(20), mfa_verified_at TIMESTAMP)`",
    targetQuery: `SELECT r.event_id, r.role_arn, m.user_arn, m.mfa_auth_type,\n       TIMESTAMPDIFF(SECOND, m.mfa_verified_at, r.assumed_at) AS seconds_since_mfa\nFROM RoleAssumes r\nINNER JOIN MfaSessions m\n  ON r.session_token = m.session_token\nWHERE r.role_arn LIKE '%Administrator%'\n  AND TIMESTAMPDIFF(SECOND, m.mfa_verified_at, r.assumed_at) > 3600\nORDER BY seconds_since_mfa DESC;`,
    eli5Story: "Checking if someone who logged into the main company cloud with super-admin powers used a hardware security key within the last hour.",
