    targetQuery: `SELECT k.brand_name,\n       COUNT(c.pickup_id) AS total_orders_fulfilled,\n       ROUND(AVG(TIMESTAMPDIFF(MINUTE, c.courier_arrived_at, c.order_scanned_at)), 1) AS avg_courier_wait_min,\n       SUM(CASE WHEN TIMESTAMPDIFF(MINUTE, c.courier_arrived_at, c.order_scanned_at) > 10 THEN 1 ELSE 0 END) AS excessive_wait_incidents\nFROM CourierPickups c\nINNER JOIN KitchenTickets k\n  ON c.order_id = k.order_id\nGROUP BY k.brand_name\nHAVING COUNT(c.pickup_id) >= 20\nORDER BY avg_courier_wait_min DESC;`,
